import {test,after,beforeEach,afterEach} from 'node:test';
import assert from 'node:assert/strict';
import {register} from 'node:module';
import {Window} from 'happy-dom';
import {unzipSync,strFromU8} from 'fflate';
register('./jsx-loader.mjs',import.meta.url);
const window=new Window({url:'http://localhost/#/data?db=commerce.db&table=customers'});
for(const name of ['window','document','navigator','HTMLElement','Element','Event','MouseEvent','PointerEvent','KeyboardEvent','localStorage','location'])Object.defineProperty(globalThis,name,{configurable:true,value:name==='window'?window:window[name]});
globalThis.IS_REACT_ACT_ENVIRONMENT=true;
globalThis.requestAnimationFrame=cb=>setTimeout(cb,0);globalThis.cancelAnimationFrame=clearTimeout;
Object.defineProperty(window.HTMLElement.prototype,'clientWidth',{configurable:true,get(){return this.classList.contains('graph-scroll')?360:1000;}});
Object.defineProperty(window.HTMLElement.prototype,'clientHeight',{configurable:true,get(){return this.classList.contains('graph-scroll')?500:800;}});
const {default:React,act}=await import('react');const {createRoot}=await import('react-dom/client');
const {default:App,RowEditor}=await import('../src/App.jsx');const {default:Graph}=await import('../src/Graph.jsx');
const {engine,calls}=await import('./rpc.mjs');
let root,host;const downloads=[],blobs=new Map();
const originalCreate=URL.createObjectURL,originalRevoke=URL.revokeObjectURL;
URL.createObjectURL=blob=>{const url='blob:quarry/'+blobs.size;blobs.set(url,blob);return url;};URL.revokeObjectURL=()=>{};
window.HTMLAnchorElement.prototype.click=function(){downloads.push({name:this.download,url:this.href});};
const settle=async(ms=35)=>act(async()=>{await new Promise(r=>setTimeout(r,ms));});
const mount=async(component=React.createElement(App))=>{await act(async()=>root.render(component));await settle();};
const button=name=>[...document.querySelectorAll('button')].filter(b=>{for(let el=b;el;el=el.parentElement)if(el.inert)return false;return true;}).find(b=>b.getAttribute('aria-label')===name||b.textContent.trim()===name)||[...document.querySelectorAll('.view-tabs>button')].find(b=>b.textContent.startsWith(name));
const click=async el=>{assert.ok(el,'Expected control exists');await act(async()=>el.click());await settle();};
const fill=async(el,value)=>{assert.ok(el);await act(async()=>{const prototype=el.tagName==='TEXTAREA'?window.HTMLTextAreaElement.prototype:window.HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(prototype,'value').set.call(el,value);el.dispatchEvent(new window.Event('input',{bubbles:true}));el.dispatchEvent(new window.Event('change',{bubbles:true}));});await settle();};
const select=async(el,value)=>{assert.ok(el);await act(async()=>{el.value=value;el.dispatchEvent(new window.Event('change',{bubbles:true}));});await settle();};
const submit=async form=>{await act(async()=>form.dispatchEvent(new window.Event('submit',{bubbles:true,cancelable:true})));await settle();};
const waitUntil=async(predicate)=>{for(let i=0;i<40;i++){if(predicate())return;await settle(25);}assert.ok(predicate(),document.body.textContent);};
const gridRows=()=>[...document.querySelectorAll('.data-grid tbody tr')];
const importDatabase=async(sql)=>{const db=new engine.SQL.Database();db.run(sql);const file=new File([db.export()],'fixture.db');db.close();const input=document.querySelector('input[type=file]');Object.defineProperty(input,'files',{configurable:true,value:[file]});await act(async()=>input.dispatchEvent(new window.Event('change',{bubbles:true})));await settle();};
beforeEach(async()=>{window.location.hash='/data?db=commerce.db&table=customers';window.localStorage.clear();window.localStorage.setItem("squeaklite-intro-seen","1");window.innerWidth=1024;downloads.length=0;blobs.clear();calls.length=0;host=document.createElement('div');document.body.append(host);root=createRoot(host);});
afterEach(async()=>{await act(async()=>root.unmount());host.remove();await settle(5);});
after(async()=>{engine.db?.close();URL.createObjectURL=originalCreate;URL.revokeObjectURL=originalRevoke;await window.happyDOM.close();});

test('table browse, pagination, sorting, search, filters and column controls',async()=>{
 await mount();assert.equal(gridRows().length,25);assert.match(document.body.textContent,/128/);
 await click(button('Next page'));assert.match(document.querySelector('.pagination').textContent,/26–50/);
 await fill(document.querySelector('[aria-label="Search table rows"]'),'Olivia');await settle(220);assert.equal(gridRows().length,8);
 await click(button('Clear search'));await settle(220);assert.equal(gridRows().length,25);
 await click([...document.querySelectorAll('.column-heading')].find(b=>b.textContent.startsWith('id')));await click([...document.querySelectorAll('.column-heading')].find(b=>b.textContent.startsWith('id')));assert.match(gridRows()[0].textContent,/128/);
 await click(button('Columns'));const col=[...document.querySelectorAll('.columns-popover label')].find(l=>l.textContent==='email');await click(col.querySelector('input'));assert.ok(![...document.querySelectorAll('.column-heading')].some(b=>b.textContent.startsWith('email')));await click(button('Close column selection'));
 await click(button('Filter'));const dialog=document.querySelector('[role=dialog]');await select(dialog.querySelector('select'),'country');await fill(dialog.querySelector('input:not([type=checkbox])'),'Germany');await submit(dialog.querySelector('form'));assert.equal(gridRows().length,16);assert.ok(gridRows().every(r=>r.textContent.includes('Germany')));
});

test('row form saves data, shows constraint errors inside the dialog, and ZIP export contains the edit',async()=>{
 await mount();await click(gridRows()[0]);await fill(document.getElementById('field-email'),'phoenix.baker@layers.design');await submit(document.querySelector('[role=dialog] form'));assert.match(document.querySelector('[role=dialog]').textContent,/UNIQUE constraint failed/);assert.ok(document.querySelector('[role=dialog] [role=alert]'));
 await fill(document.getElementById('field-email'),'olivia.updated@example.test');await fill(document.getElementById('field-name'),'Updated Olivia');await submit(document.querySelector('[role=dialog] form'));assert.equal(document.querySelector('[role=dialog]'),null);assert.equal(engine.values('SELECT name FROM customers WHERE id=1')[0].name,'Updated Olivia');
 await click(button('Export ZIP'));assert.equal(downloads.at(-1).name,'squeaklite-workspace.zip');const entries=unzipSync(new Uint8Array(await blobs.get(downloads.at(-1).url).arrayBuffer()));const check=new engine.SQL.Database(entries['commerce.db']);assert.equal(check.exec('SELECT email FROM customers WHERE id=1')[0].values[0][0],'olivia.updated@example.test');assert.match(strFromU8(entries['README.txt']),/sample/);check.close();
});

test('raw SQL, multi-results, failed-query cleanup, history and saving a query',async()=>{
 await mount();await click(button('Query'));const editor=document.querySelector('[aria-label="SQL query editor"]');await fill(editor,'SELECT 42 AS answer; SELECT 7 AS other;');await click(button('Run query'));assert.match(document.querySelector('.query-results').textContent,/42/);await click(button('Statement 2'));assert.match(document.querySelector('.query-results').textContent,/7/);
 await fill(editor,'SELECT * FROM missing_table;');await click(button('Run query'));assert.match(document.body.textContent,/no such table/);assert.equal(document.querySelectorAll('.query-results .data-grid').length,0);
 await click(button('Query history'));assert.match(document.querySelector('[role=dialog]').textContent,/SELECT 42/);await click(button('Close dialog'));
 await fill(editor,'SELECT 99 AS saved_value;');await click(button('Save query'));await fill(document.querySelector('[role=dialog] input'),'My query');await submit(document.querySelector('[role=dialog] form'));assert.equal(JSON.parse(localStorage.getItem('quarry-queries'))[0].name,'My query');await click(button('My query'));assert.match(editor.value,/saved_value/);
});

test('visual query builder joins, selects joined fields, aggregates and clears removed references',async()=>{
 await mount();await click(button('Query'));await click(button('Visual builder'));const builder=document.querySelector('.builder');await select(builder.querySelector('.builder-top select'),'orders');await click(button('Add join'));assert.match(builder.textContent,/customers.name/);
 const field=[...builder.querySelectorAll('.column-chips label')].find(l=>l.textContent==='customers.name');await click(field.querySelector('input'));await click(button('Run query'));assert.equal(document.querySelectorAll('.query-results .data-grid tbody tr').length,100);
 await click(button('Remove join'));assert.ok(!builder.querySelector('.sql-preview').textContent.includes('customers.name'));
 const aggregate=[...builder.querySelectorAll('.builder-bottom label')].find(l=>l.textContent.startsWith('Aggregate')&&!l.textContent.startsWith('Aggregate column'));await select(aggregate.querySelector('select'),'SUM');assert.ok(!builder.querySelector('.sql-preview').textContent.includes('SUM(*)'));await click(button('Run query'));assert.equal(document.querySelectorAll('.query-results .data-grid tbody tr').length,1);
});

test('database import, insert with explicit NULL, row delete, schema and read-only view',async()=>{
 await mount();await importDatabase("CREATE TABLE notes(id INTEGER PRIMARY KEY,body TEXT DEFAULT 'fallback');INSERT INTO notes(body) VALUES('existing');CREATE VIEW note_view AS SELECT * FROM notes;CREATE TABLE nullable_key(a TEXT PRIMARY KEY,body TEXT);");assert.equal(gridRows().length,1,JSON.stringify({hash:location.hash,text:document.body.textContent,calls:calls.map(c=>({method:c.method,args:c.method==='browse'?c.args:undefined}))}));await click(button('Add row'));const body=document.getElementById('field-body').closest('.form-field');await click([...body.querySelectorAll('label')].find(l=>l.textContent==='NULL').querySelector('input'));await submit(document.querySelector('[role=dialog] form'));assert.equal(engine.values('SELECT body FROM notes WHERE id=2')[0].body,null);
 await click(button('Structure'));assert.match(document.body.textContent,/fallback/);await click(button('Data'));await click(gridRows()[1]);await click(button('Delete row'));await click(button('Confirm deletion'));assert.equal(engine.values('SELECT COUNT(*) AS n FROM notes')[0].n,1n);
 await click(button('nullable_key'));await click(button('Structure'));const schemaRow=[...document.querySelectorAll('.schema-grid tbody tr')].find(r=>r.firstElementChild.textContent==='a');assert.match(schemaRow.textContent,/Nullable/);await click(button('note_view'));await waitUntil(()=>gridRows().length>0);assert.equal(button('Add row'),undefined);await click(gridRows()[0]);assert.match(document.querySelector('[role=dialog]').textContent,/Inspect row/);assert.equal(button('Save changes'),undefined);
});

test('self-referencing FK navigation changes the filter without a timeout race',async()=>{
 await mount();await importDatabase('CREATE TABLE people(id INTEGER PRIMARY KEY,name TEXT,manager INTEGER REFERENCES people(id));INSERT INTO people VALUES(1,\'Manager\',NULL),(2,\'Report\',1);');await click(gridRows()[1]);await click([...document.querySelectorAll('.relation-link')][0]);assert.equal(gridRows().length,1);assert.match(gridRows()[0].textContent,/Manager/);assert.ok(location.hash.includes('where='));
});

test('graph buttons, pinch, cancelled pointers, tap navigation and fullscreen fallback',async()=>{
 await engine.demo();let opened='';await mount(React.createElement(Graph,{objects:engine.meta().objects,onTable:t=>opened=t}));const area=document.querySelector('.graph-scroll'),canvas=document.querySelector('.graph-canvas');const initial=canvas.style.transform;await click(button('Zoom in'));assert.notEqual(canvas.style.transform,initial);await click(button('Fit graph'));assert.equal(canvas.style.transform,initial);
 const pointer=async(type,id,x,y,target=area)=>{await act(async()=>target.dispatchEvent(new window.PointerEvent(type,{bubbles:true,pointerId:id,pointerType:'touch',clientX:x,clientY:y,button:0})));};
 await pointer('pointerdown',1,100,100);await pointer('pointerdown',2,200,100);await pointer('pointermove',2,300,100);assert.notEqual(canvas.style.transform,initial);await pointer('pointerup',2,300,100);await pointer('pointercancel',1,100,100);
 const title=document.querySelector('.graph-node-title');await pointer('pointerdown',3,120,120,title);await pointer('pointerup',3,120,120,title);await click(title);assert.ok(opened);
 const panel=document.querySelector('.graph-panel');panel.requestFullscreen=()=>Promise.reject(new Error('Not supported'));await click(button('Enter full screen'));assert.ok(panel.classList.contains('graph-expanded'));assert.equal(button('Exit full screen').getAttribute('aria-pressed'),'true');await act(async()=>document.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Escape',bubbles:true})));assert.ok(!panel.classList.contains('graph-expanded'));
});

test('fullscreen follows native browser exit and a failed import remains readable in its dialog',async()=>{
 await engine.demo();await mount(React.createElement(Graph,{objects:engine.meta().objects,onTable:()=>{}}));const panel=document.querySelector('.graph-panel');panel.requestFullscreen=async()=>{Object.defineProperty(document,'fullscreenElement',{configurable:true,value:panel});document.dispatchEvent(new window.Event('fullscreenchange'));};await click(button('Enter full screen'));assert.ok(panel.classList.contains('graph-expanded'));await act(async()=>{Object.defineProperty(document,'fullscreenElement',{configurable:true,value:null});document.dispatchEvent(new window.Event('fullscreenchange'));});assert.ok(!panel.classList.contains('graph-expanded'));
 await act(async()=>root.unmount());root=createRoot(host);await mount();await click(button('Import workspace'));const input=document.querySelector('input[type=file]');Object.defineProperty(input,'files',{configurable:true,value:[new File(['invalid'],'bad.db')]});await act(async()=>input.dispatchEvent(new window.Event('change',{bubbles:true})));await settle();assert.match(document.querySelector('[role=dialog] [role=alert]').textContent,/No SQLite/);assert.equal(engine.browse({table:'customers'}).count,128n);
});


test('SQL starts empty; the table-aware suggestion inserts only on request and never executes itself',async()=>{
 await mount();await click(button('Query'));const editor=document.querySelector('[aria-label="SQL query editor"]');assert.equal(editor.value,'');assert.equal(button('Run query').disabled,true);assert.equal(button('Save query').disabled,true);const queries=()=>calls.filter(c=>c.method==='query').length;const before=queries();await act(async()=>window.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Enter',ctrlKey:true,bubbles:true})));assert.equal(queries(),before);
 await click(button('Insert SELECT'));assert.match(editor.value,/FROM "customers"/);assert.equal(queries(),before);assert.equal(button('Run query').disabled,false);await click(button('Run query'));assert.equal(document.querySelectorAll('.query-results .data-grid tbody tr').length,100);
 await fill(editor,'SELECT 321 AS my_query;');await click(button('Data'));await click(button('orders'));await click(button('Query'));assert.equal(document.querySelector('[aria-label="SQL query editor"]').value,'SELECT 321 AS my_query;');
});

const touch=async(el,type,id,x,y)=>{const event=new window.PointerEvent(type,{bubbles:true,cancelable:true,pointerId:id,pointerType:'touch',clientX:x,clientY:y,button:0});await act(async()=>el.dispatchEvent(event));return event;};
const mobileTable=async()=>{window.innerWidth=375;await mount();const area=document.querySelector('.data-scroll');Object.defineProperties(area,{clientWidth:{configurable:true,value:320},clientHeight:{configurable:true,value:260},scrollWidth:{configurable:true,value:1320},scrollHeight:{configurable:true,value:1800}});await act(async()=>area.dispatchEvent(new window.Event('scroll')));await settle();return area;};

test('steady table drag locks its axis, damps movement, has no release momentum, and suppresses row opening',async()=>{
 const area=await mobileTable();assert.equal(area.style.touchAction,'pinch-zoom');assert.equal(area.tabIndex,0);assert.ok(button('Use native table scrolling'));await touch(area,'pointerdown',1,200,100);await touch(area,'pointermove',1,100,90);assert.equal(area.scrollLeft,65);assert.equal(area.scrollTop,0);await touch(area,'pointermove',1,80,-200);assert.equal(area.scrollLeft,78);assert.equal(area.scrollTop,0);await touch(area,'pointerup',1,80,-200);await settle(90);assert.equal(area.scrollLeft,78);
 const row=gridRows()[0];await act(async()=>row.dispatchEvent(new window.MouseEvent('click',{bubbles:true,cancelable:true,detail:1})));assert.equal(document.querySelector('[role=dialog]'),null);await touch(row,'pointerdown',2,100,100);await touch(row,'pointerup',2,100,100);await act(async()=>row.dispatchEvent(new window.MouseEvent('click',{bubbles:true,cancelable:true,detail:1})));assert.ok(document.querySelector('[role=dialog]'));
});

test('table pinch is not cancelled, and native mode preserves browser handling and the saved preference',async()=>{
 const area=await mobileTable();await touch(area,'pointerdown',1,100,100);await touch(area,'pointerdown',2,200,100);const event=await touch(area,'pointermove',2,300,100);assert.equal(event.defaultPrevented,false);assert.equal(area.scrollLeft,0);assert.equal(area.scrollTop,0);await touch(area,'pointerup',2,300,100);await touch(area,'pointermove',1,50,100);assert.equal(area.scrollLeft,0);await touch(area,'pointercancel',1,50,100);
 const wheel=new window.WheelEvent('wheel',{bubbles:true,cancelable:true,ctrlKey:true,deltaY:-20});area.dispatchEvent(wheel);assert.equal(wheel.defaultPrevented,false);await click(button('Use native table scrolling'));assert.equal(area.style.touchAction,'manipulation');assert.equal(localStorage.getItem('quarry-table-scroll'),'native');await touch(area,'pointerdown',3,200,100);await touch(area,'pointermove',3,100,100);assert.equal(area.scrollLeft,0);await touch(area,'pointerup',3,100,100);
 await click(button('Structure'));assert.ok(button('Use steady table scrolling'));assert.equal(document.querySelector('.data-scroll').style.touchAction,'manipulation');
});

test('table step controls stay bounded and scrollbars, keyboard focus and vertical overflow remain available',async()=>{
 const area=await mobileTable();assert.equal(button('Scroll table left').disabled,true);await click(button('Scroll table right'));assert.equal(area.scrollLeft,208);await click(button('Scroll table left'));assert.equal(area.scrollLeft,0);await touch(area,'pointerdown',1,100,200);await touch(area,'pointermove',1,90,100);assert.equal(area.scrollTop,65);assert.equal(area.scrollLeft,0);await touch(area,'pointercancel',1,90,100);
 await act(async()=>{area.focus();});assert.equal(document.activeElement,area);const key=new window.KeyboardEvent('keydown',{bubbles:true,cancelable:true,key:'ArrowDown'});area.dispatchEvent(key);assert.equal(key.defaultPrevented,false);
 Object.defineProperties(area,{scrollWidth:{configurable:true,value:320},scrollHeight:{configurable:true,value:260}});await act(async()=>area.dispatchEvent(new window.Event('scroll')));await settle();assert.equal(area.style.touchAction,'manipulation');
});

const lastDialog=()=>[...document.querySelectorAll('[role=dialog]')].at(-1);
test('sample deletion is explained, cancellation preserves selection, and successful deletion clears every checkbox',async()=>{
 await mount();await click(document.querySelector('[aria-label="Select row 1"]'));await click(button('Delete 1'));assert.match(lastDialog().textContent,/Deletion blocked/);assert.match(lastDialog().textContent,/addresses/);assert.match(lastDialog().textContent,/orders/);assert.equal(button('Confirm deletion'),undefined);assert.equal(engine.browse({table:'customers'}).count,128n);await click(button('Close'));assert.equal(document.querySelector('[aria-label="Select row 1"]').checked,true);
 await click(button('payments'));await waitUntil(()=>gridRows().length===25);assert.equal(document.querySelector('[aria-label="Select row 1"]').checked,false);await click(document.querySelector('[aria-label="Select row 1"]'));await click(document.querySelector('[aria-label="Select row 2"]'));await click(button('Delete 2'));assert.equal(engine.browse({table:'payments'}).count,384n);await click(button('Cancel'));assert.ok(button('Delete 2'));assert.equal(engine.browse({table:'payments'}).count,384n);await click(button('Delete 2'));await click(button('Confirm deletion'));await waitUntil(()=>gridRows().length===25);assert.equal(engine.browse({table:'payments'}).count,382n);assert.equal(button('Delete 2'),undefined);assert.ok([...document.querySelectorAll('.data-grid input[type=checkbox]')].every(i=>!i.checked));assert.ok(!document.querySelector('.pagination').textContent.includes('selected'));
});
