const movingFixture="CREATE TABLE items(id INTEGER PRIMARY KEY,label TEXT NOT NULL,bucket TEXT);WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<40) INSERT INTO items SELECT x,printf('item%02d',x),'visible' FROM n;";
test('saved row is located, focused and highlighted after sort/page and primary-key changes',async()=>{
 await mount();await importDatabase(movingFixture);await click([...document.querySelectorAll('.column-heading')].find(b=>b.textContent.startsWith('label')));await click(gridRows()[0]);await fill(document.getElementById('field-label'),'zzzz saved');await fill(document.getElementById('field-id'),'9223372036854775806');await click(button('Save changes'));
 await waitUntil(()=>document.querySelector('[data-row-highlight]'));const row=document.querySelector('[data-row-highlight]');assert.match(row.textContent,/zzzz saved/);assert.match(row.dataset.rowKey,/9223372036854775806/);assert.equal(document.activeElement,row);assert.match(document.querySelector('.pagination').textContent,/Page 2 of 2/);assert.equal(engine.values("SELECT id FROM items WHERE label='zzzz saved'")[0].id,9223372036854775806n);
 await settle(2850);assert.equal(document.querySelector('[data-row-highlight]'),null);
});
test('editing a row out of an active search preserves search and explains why it is hidden',async()=>{
 await mount();await importDatabase(movingFixture);await fill(document.querySelector('[aria-label="Search table rows"]'),'item01');await settle(220);await click(gridRows()[0]);await fill(document.getElementById('field-label'),'renamed');await click(button('Save changes'));await settle(250);assert.equal(document.querySelector('[aria-label="Search table rows"]').value,'item01');assert.equal(gridRows().length,0);assert.match(document.querySelector('.toast').textContent,/no longer visible/);assert.equal(document.querySelector('[data-row-highlight]'),null);
});
test('successful deletion animates a snapshot and clears selection; failed deletion leaves the row and modal intact',async()=>{
 await mount();await importDatabase("CREATE TABLE notes(id INTEGER PRIMARY KEY,body TEXT);INSERT INTO notes VALUES(1,'delete this'),(2,'keep this');");await click(gridRows()[0]);await click(button('Delete row'));const remove=engine.deleteRows;engine.deleteRows=()=>{throw new Error('Simulated deletion error');};try{await click(button('Confirm deletion'));assert.match(lastDialog().textContent,/Simulated deletion error/);assert.equal(gridRows().length,2);assert.equal(document.querySelector('.deleted-row-snapshot'),null);}finally{engine.deleteRows=remove;}
 await click(button('Review again'));await click(button('Confirm deletion'));assert.equal(lastDialog(),undefined);assert.equal(gridRows().length,1);assert.match(gridRows()[0].textContent,/keep this/);assert.match(document.querySelector('.deleted-row-snapshot').textContent,/delete this/);assert.equal(document.querySelector('.deleted-row-snapshot').getAttribute('aria-hidden'),'true');await settle(550);assert.equal(document.querySelector('.deleted-row-snapshot'),null);
});
test('stale row forms preserve user input and never overwrite newer values',async()=>{
 await mount();await importDatabase(movingFixture);await click(gridRows()[0]);await fill(document.getElementById('field-label'),'my draft');engine.edit({table:'items',key:{id:1},action:'update',values:{label:'newer value'}});await click(button('Save changes'));assert.match(lastDialog().textContent,/changed while this form/);assert.equal(document.getElementById('field-label').value,'my draft');assert.equal(engine.values('SELECT label FROM items WHERE id=1')[0].label,'newer value');assert.equal(document.querySelector('[data-row-highlight]'),null);
});
test('committed insert with a failed metadata refresh closes the form and cannot be retried as a duplicate',async()=>{
 await mount();await importDatabase("CREATE TABLE notes(id INTEGER PRIMARY KEY,body TEXT);");await click(button('Add row'));await fill(document.getElementById('field-body'),'insert once');const workspace=engine.workspace;engine.workspace=async()=>{throw new Error('Simulated refresh failure');};try{await submit(lastDialog().querySelector('form'));assert.equal(lastDialog(),undefined);assert.equal(engine.values('SELECT COUNT(*) n FROM notes')[0].n,1n);assert.match(document.querySelector('.global-error').textContent,/operation finished, but refreshing.*Simulated refresh failure/);}finally{engine.workspace=workspace;}
});
test('JOIN assistant offers reverse/composite keys, INNER joins and grouping; manual chained joins remove dependent fields',async()=>{
 await mount();await importDatabase("CREATE TABLE parent(a TEXT,b INTEGER,PRIMARY KEY(a,b)) WITHOUT ROWID;CREATE TABLE child(id INTEGER PRIMARY KEY,x TEXT,y INTEGER,FOREIGN KEY(x,y) REFERENCES parent);CREATE TABLE extra(id INTEGER PRIMARY KEY,child_id INTEGER);INSERT INTO parent VALUES('a',1),('b',2);INSERT INTO child VALUES(1,'a',1),(2,'a',1);INSERT INTO extra VALUES(1,1);");await click(button('Query'));await click(button('Visual builder'));await select(document.querySelector('.builder-top select'),'parent');await select(document.querySelector('[aria-label="Join table"]'),'child');assert.equal(document.querySelectorAll('.join-pair').length,2);assert.match(document.querySelector('[aria-label="Join relationship"]').textContent,/parent.a = child.x.*parent.b = child.y/);await select(document.querySelector('[aria-label="Join type"]'),'INNER');await click(button('Add join'));assert.match(document.querySelector('.sql-preview').textContent,/INNER JOIN "child"/);
 const aggregate=[...document.querySelectorAll('.builder-bottom label')].find(l=>l.textContent.startsWith('Aggregate')&&!l.textContent.startsWith('Aggregate column'));await select(aggregate.querySelector('select'),'COUNT');const group=[...document.querySelectorAll('.builder-bottom label')].find(l=>l.textContent.startsWith('Group by'));await select(group.querySelector('select'),'a');await click(button('Run query'));assert.match(document.querySelector('.query-results').textContent,/aggregate_value/);assert.equal(document.querySelectorAll('.query-results tbody tr').length,1);
 await select(document.querySelector('[aria-label="Join table"]'),'extra');await select(document.querySelector('[aria-label="Join from"]'),'child');await select(document.querySelector('[aria-label="Join source column 1"]'),'id');await select(document.querySelector('[aria-label="Join target column 1"]'),'child_id');await click(button('Add join'));assert.match(document.querySelector('.sql-preview').textContent,/"child"\."id" = "extra"\."child_id"/);await select(group.querySelector('select'),'extra.id');await click(button('Remove join'));assert.ok(!document.querySelector('.sql-preview').textContent.includes('extra'));assert.ok(!document.querySelector('.sql-preview').textContent.includes('JOIN'));
});

test('schema mutation refresh prunes stale builder columns, filters and grouping without losing valid joins',async()=>{
 await mount();await click(button('Query'));await click(button('Visual builder'));await select(document.querySelector('.builder-top select'),'orders');await click(button('Add join'));await click([...document.querySelectorAll('.column-chips label')].find(l=>l.textContent==='customers.name').querySelector('input'));
 const group=[...document.querySelectorAll('.builder-bottom label')].find(l=>l.textContent.startsWith('Group by'));await select(group.querySelector('select'),'customers.name');await click(button('Add condition'));await select(document.querySelector('[aria-label="Condition 1 column"]'),'customers.name');await click(button('SQL editor'));await fill(document.querySelector('[aria-label="SQL query editor"]'),'ALTER TABLE customers RENAME COLUMN name TO full_name;');await click(button('Run query'));await click(button('Confirm and run'));await click(button('Visual builder'));
 const preview=document.querySelector('.sql-preview').textContent;assert.ok(!preview.includes('customers.name'));assert.ok(!preview.includes('GROUP BY'));assert.ok(!preview.includes('WHERE'));assert.match(preview,/JOIN "customers"/);assert.ok([...document.querySelectorAll('.column-chips label')].some(l=>l.textContent==='customers.full_name'));
});
